const logo='https://hc-vitkovice.esports.cz/files/logos/logo_VIT_invert.png';
const matches=[{id:'lib',opponent:'Bílí Tygři Liberec',short:'LIBEREC',date:'2026-10-20T17:30:00+02:00',round:15,logo:'https://hc-vitkovice.esports.cz/files/logos/LIB.png'},{id:'kom',opponent:'HC Kometa Brno',short:'KOMETA BRNO',date:'2026-10-23T17:30:00+02:00',round:13},{id:'tri',opponent:'HC Oceláři Třinec',short:'TŘINEC',date:'2026-11-01T17:30:00+01:00',round:17}];
const players=[{name:'Jakub Zbořil',number:38,position:'Obránce',born:'21. 2. 1997'},{name:'Šimon Stránský',number:14,position:'Útočník',born:'21. 12. 1997'},{name:'Anthony Nellis',number:19,position:'Útočník',born:'10. 9. 1994'},{name:'Dominik Hrachovina',number:49,position:'Brankář',born:'29. 8. 1994'},{name:'Marek Kalus',number:11,position:'Útočník',born:'22. 7. 1993'},{name:'David Cienciala',number:81,position:'Útočník',born:'1. 12. 1995'}];
let tips={};try{tips=JSON.parse(localStorage.getItem('vitkovice-vip-tips')||'{}');if(!tips||typeof tips!=='object'||Array.isArray(tips))tips={}}catch{}let selectedId=matches.find(m=>new Date(m.date)>new Date())?.id||matches[0].id;let outcome='';
const main=document.querySelector('#main'),dialog=document.querySelector('#dialog');
const dateFormat=(date,options)=>new Intl.DateTimeFormat('cs-CZ',{timeZone:'Europe/Prague',...options}).format(new Date(date));
const isOpen=m=>Date.now()<new Date(m.date).getTime();
function rankRows(){return [['1','PN','Petr Novák',142],['2','MS','Martin Svoboda',136],['3','LD','Lucie Dvořáková',128],['4','TH','Tomáš Horák',121],['5','JK','Jan Kovář · vy',0]].map(([n,i,name,pts])=>`<div class="rank-row ${n==='5'?'me':''}"><span class="place">${n}.</span><span class="avatar">${i}</span><span>${name}</span><b>${pts}</b></div>`).join('')}
function schedule(){return matches.map(m=>`<div class="schedule-row"><div class="date-block"><b>${dateFormat(m.date,{day:'numeric'})}</b>${dateFormat(m.date,{month:'short'})}</div><div><strong>Vítkovice <span style="color:#9aa6b5">vs.</span> ${m.opponent}</strong><small>${dateFormat(m.date,{weekday:'long',hour:'2-digit',minute:'2-digit'})} · ${m.round}. kolo · domácí utkání</small></div><button data-match="${m.id}">${!isOpen(m)?'Uzavřeno':tips[m.id]?'Upravit tip':'Tipovat →'}</button></div>`).join('')}
function hero(m){return `<section class="hero"><div class="hero-top"><span>NEJBLIŽŠÍ VYBRANÝ DOMÁCÍ ZÁPAS</span><span class="live">● ${isOpen(m)?'TIPOVÁNÍ OTEVŘENO':'TIPOVÁNÍ UZAVŘENO'}</span></div><div class="matchup"><div class="team"><img src="${logo}" alt="HC Vítkovice Ridera"><strong>VÍTKOVICE RIDERA</strong><small>DOMÁCÍ</small></div><span class="versus">VS</span><div class="team"><div style="font:800 49px 'Barlow Condensed',sans-serif;height:80px;display:grid;place-items:center;letter-spacing:-2px;color:#e2ebf7">${m.id==='lib'?'LIB':m.id==='kom'?'KOM':'TRI'}</div><strong>${m.short}</strong><small>HOSTÉ</small></div></div><div class="match-info">${dateFormat(m.date,{day:'numeric',month:'long',year:'numeric'})} &nbsp; / &nbsp; ${dateFormat(m.date,{hour:'2-digit',minute:'2-digit'})} &nbsp; / &nbsp; ${m.round}. kolo</div><div class="countdown"><span>◷ &nbsp; Do uzavření tipů zbývá</span><b id="countdown">—</b></div></section>`}
function tipForm(m){const t=tips[m.id];outcome=t?.outcome||'';return `<section class="card tip-card"><div class="section-head"><h2>Jak to podle tebe dopadne?</h2><span class="pill">${t?'TIP ULOŽEN':'TVŮJ TIP'}</span></div><p class="hint" style="margin:9px 0 0">Tipuj výsledek po 60 minutách. Každý správný odhad se počítá.</p><form id="tip-form"><label class="field-label">Výsledek v základní hrací době</label><div class="choices">${[['1','Vítkovice'],['X','Remíza'],['2',m.short]].map(([v,n])=>`<button type="button" data-outcome="${v}" aria-pressed="${outcome===v}" class="choice ${outcome===v?'selected':''}"><b>${v}</b>${n}</button>`).join('')}</div><div class="form-row"><div><label class="field-label" for="home-score">Přesné skóre <span class="hint">(nepovinné)</span></label><div class="score"><input id="home-score" aria-label="Góly Vítkovice" type="number" min="0" max="30" value="${Number.isInteger(t?.home)?t.home:''}" placeholder="–"><span>:</span><input id="away-score" aria-label="Góly soupeře" type="number" min="0" max="30" value="${Number.isInteger(t?.away)?t.away:''}" placeholder="–"></div></div><div><label class="field-label" for="goals">Celkový počet gólů</label><select id="goals"><option value="">Bez tipu</option><option value="under" ${t?.goals==='under'?'selected':''}>Méně než 5,5</option><option value="over" ${t?.goals==='over'?'selected':''}>Více než 5,5</option></select></div></div><div class="submit-row"><span class="save-note">${t?'✓ Uloženo v tomto prohlížeči':'⌁ Tip můžeš měnit do začátku zápasu.'}</span><button class="primary" ${!isOpen(m)?'disabled':''}>${!isOpen(m)?'Tipování uzavřeno':t?'Upravit můj tip →':'Uložit můj tip →'}</button></div></form></section>`}
function intro(title,description){return `<div class="intro"><div><span class="eyebrow">TVŮJ KLUB. TVŮJ ODHAD.</span><h1>${title}</h1><p>${description}</p></div><span class="date">${dateFormat(new Date(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span></div>`}
function render(){let view=location.hash.slice(1)||'prehled';if(!['prehled','zapasy','tipy','zebricek','hraci'].includes(view))view='prehled';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.view===view));document.querySelector('#page-name').textContent={prehled:'Přehled',zapasy:'Domácí zápasy',tipy:'Moje tipy',zebricek:'Žebříček',hraci:'Náš tým'}[view];const m=matches.find(x=>x.id===selectedId);
if(view==='prehled')main.innerHTML=intro('Na ledě tým. Ve hře ty.','Vítej ve VIP klubu. Další domácí zápas je další šance ukázat svůj přehled.')+`<div class="grid"><div>${hero(m)}${tipForm(m)}<section class="bottom card"><div class="section-head"><h2>Další zápasy na domácím ledě</h2></div>${schedule()}</section></div><aside class="right-column"><section class="card stats-card"><span class="stat-top">TVÁ SEZÓNA V ČÍSLECH</span><div class="points">0 <small>bodů</small></div><div class="stat-meta"><span>${Object.keys(tips).length} uložených tipů</span><span>Čeká na vyhodnocení</span></div></section><section class="card ranking"><div class="section-head"><h2>VIP žebříček</h2><span class="pill">DEMO</span></div><p class="hint">Ukázkové pořadí soutěžících</p>${rankRows()}<a href="#zebricek" class="link">Celý žebříček &nbsp; →</a></section><section class="club-note"><span class="eyebrow">HRAJEME SPOLU</span><h2 style="margin:9px 0">Věrnost má svoje místo.</h2><p>Domácí led, společné emoce a tvoje tipy. Exkluzivně pro členy VIP klubu.</p><a class="link" href="https://www.hc-vitkovice.cz/" target="_blank" rel="noopener">Novinky z klubu ↗</a></section></aside></div>`;
if(view==='zapasy')main.innerHTML=intro('Domácí led. Velké zápasy.','Tipování se automaticky uzavírá v okamžiku plánovaného začátku utkání.')+`<section class="card">${schedule()}</section><p class="hint">Rozpis převzat z klubového webu 19. 10. 2026. Časy: Evropa / Praha. Prototyp zatím nesynchronizuje změny termínů.</p><section class="card bottom"><h2>Poslední domácí výsledky</h2><div class="schedule-row"><div><strong>Vítkovice – Motor České Budějovice</strong><small>16. 10. 2026 · Konečný výsledek</small></div><span class="result">1 : 3</span></div><div class="schedule-row"><div><strong>Vítkovice – Dynamo Pardubice</strong><small>9. kolo · Konečný výsledek</small></div><span class="result">2 : 3</span></div><a class="link" href="https://www.hc-vitkovice.cz/" target="_blank" rel="noopener">Zdroj: oficiální klubový web ↗</a><p class="hint">Výsledky jsou vložené ručně. Tipsport zatím není připojen.</p></section>`;
if(view==='tipy')main.innerHTML=intro('Tvoje tipy. Tvůj přehled.','Tipy uložené na tomto zařízení. Body přibudou až po připojení vyhodnocování.')+`<section class="card">${matches.filter(x=>tips[x.id]).map(x=>{const t=tips[x.id];return `<div class="schedule-row"><div><strong>Vítkovice – ${x.opponent}</strong><small>Výsledek: ${['1','X','2'].includes(t.outcome)?t.outcome:'—'} · Skóre: ${Number.isInteger(t.home)?t.home:'–'} : ${Number.isInteger(t.away)?t.away:'–'} · Góly: ${t.goals==='over'?'nad 5,5':t.goals==='under'?'pod 5,5':'bez tipu'}</small></div><button data-match="${x.id}">${isOpen(x)?'Upravit':'Uzavřeno'}</button></div>`}).join('')||'<div class="empty">Zatím nemáš žádný tip. Vyber domácí zápas a zapoj se do hry.<br><a href="#zapasy" class="link">Vybrat zápas →</a></div>'}</section>`;
if(view==='zebricek')main.innerHTML=intro('Každý bod se počítá.','VIP soutěž napříč celou sezónou.')+`<div class="notice">Ukázková data. Skutečné pořadí se zobrazí po připojení VIP účtů, databáze a vyhodnocování.</div><section class="card" style="max-width:750px"><h2>Sezónní žebříček</h2>${rankRows()}</section>`;
if(view==='hraci')main.innerHTML=intro('Znáš svůj tým?','Poznej hráče, kteří hájí vítkovické barvy.')+`<div class="players">${players.map((p,i)=>`<article class="card player-card"><span class="eyebrow">${p.position}</span><div class="player-number">${p.number}</div><h2>${p.name}</h2><p>Narozen ${p.born}</p><button class="text-button" style="color:var(--blue);padding-left:0" data-player="${i}">Profil hráče →</button></article>`).join('')}</div><p class="hint">Výběr hráčů ze soupisky na klubovém webu, ověřeno 19. 10. 2026. Kariéru a aktuální statistiky najdeš v oficiálních profilech.</p>`;
document.querySelector('#tip-form')?.addEventListener('submit',e=>{e.preventDefault();if(!isOpen(m)){showToast('Tipování tohoto zápasu je již uzavřené.');render();return}if(!outcome){showToast('Vyber vítěze nebo remízu.');return}const h=document.querySelector('#home-score').value,a=document.querySelector('#away-score').value;if((h==='')!==(a==='')){showToast('Vyplň oba počty gólů, nebo nech skóre prázdné.');return}if(h!==''&&((Number(h)>Number(a)?'1':Number(h)<Number(a)?'2':'X')!==outcome)){showToast('Přesné skóre musí odpovídat vybranému výsledku.');return}const previous=tips[m.id];tips[m.id]={outcome,home:h===''?null:Number(h),away:a===''?null:Number(a),goals:document.querySelector('#goals').value,savedAt:new Date().toISOString()};try{localStorage.setItem('vitkovice-vip-tips',JSON.stringify(tips));render();showToast('✓ Tip je uložený. Držíme Vítkovicím palce!')}catch{if(previous)tips[m.id]=previous;else delete tips[m.id];showToast('Uložení se nezdařilo. Povol úložiště prohlížeče.')}});updateCountdown();}
document.addEventListener('click',e=>{const outcomeButton=e.target.closest('[data-outcome]');if(outcomeButton){outcome=outcomeButton.dataset.outcome;document.querySelectorAll('[data-outcome]').forEach(b=>{b.classList.toggle('selected',b.dataset.outcome===outcome);b.setAttribute('aria-pressed',String(b.dataset.outcome===outcome))})}const matchButton=e.target.closest('[data-match]');if(matchButton){selectedId=matchButton.dataset.match;if(location.hash==='#prehled')render();else location.hash='prehled';window.scrollTo({top:0,behavior:'smooth'})}const playerButton=e.target.closest('[data-player]');if(playerButton){const p=players[Number(playerButton.dataset.player)];openDialog(`<span class="eyebrow">HC VÍTKOVICE RIDERA · #${p.number}</span><h1>${p.name}</h1><p>${p.position} · narozen ${p.born}</p><p>Podrobnou kariéru, předchozí působiště a sezonní statistiky najdeš přes jméno hráče na oficiální soupisce klubu.</p><a class="primary" style="display:inline-block" href="https://www.hc-vitkovice.cz/soupiska/MUZ" target="_blank" rel="noopener">Otevřít oficiální soupisku ↗</a>`)}});
function openDialog(html){document.querySelector('#dialog-content').innerHTML=html;dialog.showModal()}document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelector('#rules').onclick=()=>openDialog('<span class="eyebrow">NÁVRH PRAVIDEL</span><h1>Tipuj srdcem. Hraj fér.</h1><p>Prototyp počítá se soutěží bez peněžních vkladů. Pravidla a ceny musí před spuštěním potvrdit pořadatel.</p><ul><li>Tipujeme jen domácí zápasy HC Vítkovice.</li><li>Všechny tipy se vztahují k základní hrací době (60 minut), bez prodloužení a nájezdů.</li><li>Návrh bodování: výsledek 3 body, přesné skóre dalších 5 bodů, počet gólů další 2 body.</li><li>Hranice 5,5 znamená nejvýše 5 nebo alespoň 6 gólů.</li><li>Tip je možné měnit do plánovaného začátku zápasu.</li><li>Body, pravidla odložených zápasů a shodné pořadí zatím nejsou implementované.</li></ul><p>Demo používá místní čas zařízení. Produkční verze bude uzávěrku ověřovat na serveru a omezí přístup na schválené VIP členy.</p>');
let toastTimer;function showToast(text){const t=document.querySelector('#toast');t.textContent=text;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',4000)}
function updateCountdown(){const el=document.querySelector('#countdown');if(!el)return;const m=matches.find(x=>x.id===selectedId),delta=new Date(m.date)-Date.now();if(delta<=0){el.textContent='Tipování uzavřeno';document.querySelector('#tip-form .primary').disabled=true;document.querySelector('.live').textContent='● TIPOVÁNÍ UZAVŘENO';return}const seconds=Math.floor(delta/1000);el.textContent=`${Math.floor(seconds/86400)} d : ${String(Math.floor(seconds/3600)%24).padStart(2,'0')} h : ${String(Math.floor(seconds/60)%60).padStart(2,'0')} m : ${String(seconds%60).padStart(2,'0')} s`}
addEventListener('hashchange',render);setInterval(updateCountdown,1000);render();
